info.description:
/* Apply only on ChatGPT page using @document */
@document url("https://chat.openai.com") {

  /* Targeting the response message bubbles in ChatGPT */
  div[class*="message"]:not([class*="user"]) {
      position: relative;
      margin-bottom: 16px; /* Space for the label */
  }

  /* Add "BobGpt:" before each ChatGPT message */
  div[class*="message"]:not([class*="user"]):before {
      content: "BobGpt: ";
      position: absolute;
      top: -18px; /* Position it above the message */
      left: 0;
      font-size: 14px;
      color: #888; /* Light gray for the label */
      font-weight: bold;
      text-transform: uppercase;
  }
}

